use std::{env,fs,io::{self,Write}};use spore_core::creature_skin_index_copy_v1::copy_indices;
fn main(){let a:Vec<_>=env::args().collect();assert_eq!(a.len(),2);let b=fs::read(&a[1]).unwrap();assert_eq!(b.len(),1008);let words:Vec<_>=b.chunks_exact(4).map(|v|u32::from_le_bytes(v.try_into().unwrap())).collect();let mut output=Vec::new();for n in [0,1,252]{let mut dest=[0xa5a5a5a5;252];let count=copy_indices(&words[..n],&mut dest).unwrap();output.extend((count as u32).to_le_bytes());for v in dest{output.extend(v.to_le_bytes());}}io::stdout().write_all(&output).unwrap();}
